/** NAAC grade bands on the CGPA (RAF). */
export const NAAC_BANDS: { min: number; grade: string }[] = [
  { min: 3.51, grade: 'A++' },
  { min: 3.26, grade: 'A+' },
  { min: 3.01, grade: 'A' },
  { min: 2.76, grade: 'B++' },
  { min: 2.51, grade: 'B+' },
  { min: 2.01, grade: 'B' },
  { min: 1.51, grade: 'C' },
];
export const naacGrade = (cgpa: number | null): string => (cgpa === null ? '-' : (NAAC_BANDS.find((b) => cgpa >= b.min)?.grade ?? 'D'));

export type { MetricDef };
